      const start=ageMatch?Number(ageMatch[1]):yearsMatch?end-Number(yearsMatch[1]):null,magic=/magic|mage|arcane|spell/.test(subject.toLowerCase()),sword=/sword/.test(subject.toLowerCase()),spear=/spear/.test(subject.toLowerCase()),bow=/bow|archer/.test(subject.toLowerCase()),smith=/smith|forge/.test(subject.toLowerCase());
      const domains=magic?['Arcana']:smith?['Crafting']:bow?['Ranged']:(sword||spear)?['Melee']:['Investigation'];const caps=[];if(magic&&/arcane/.test(l))caps.push('cap_arcane_tradition');if(magic&&/\bshap(?:e|ing)\b/.test(l))caps.push('cap_magic_shape');if(magic&&/(?:\bsense\b|detect(?:ing)? magic)/.test(l))caps.push('cap_magic_sense');if(magic&&/\bward(?:ing|s)?\b/.test(l))caps.push('cap_magic_ward');if(smith)caps.push('cap_blacksmithing');if(smith&&/(?:forge tools?|hammer|anvil)/.test(l))caps.push('cap_forge_tools');if(sword)caps.push('cap_sword');if(spear)caps.push('cap_spear');if(bow)caps.push('cap_bow');if(/literacy|reading|writing|language/.test(l))caps.push('cap_basic_literacy');const f=fact(answer,'training',subject,{ambiguity:ambiguities.filter(x=>/exceeds|impossible/i.test(x)),confidence:ambiguities.length?'unresolved':'explicit'});
